// @ts-nocheck
/// The transition a `motion` component gives a key that its `transition` does not describe, against Motion 14.1.0's own
/// `animateTarget` (`fixtures/motion-default-oracle.json`, regenerated by `fixtures/motion-default-oracle.sh`). With no
/// `transition`, or one that holds only a `delay` or a repeat field, a transform key (`x`, `scale`, `rotate`, ...) is a spring,
/// more than two keyframes run for 0.8 s, and everything else is a cubic bezier over 0.3 s. Which keys a `default`, an entry for
/// another key, a `type` without a duration or the transition of a variant counts as describing is the oracle's too.
///
/// `opacity` is not read here (the test window has no cheap read of it): `motion-waapi.test.tsx` replays its default curve.

import fs from "fs"
import path from "path"
import { fileURLToPath } from "url"
import { describe, expect, it } from "vitest"
import { motion } from "../index"
import { createTestRoot, hasNativeTestRenderer } from "../testing"
import type { TestRenderer } from "../testing"

const describeNative = hasNativeTestRenderer ? describe : describe.skip

interface OracleCase {
  key: string
  from: number
  to: number | Array<number | null>
  transition?: Record<string, unknown>
  target?: Record<string, unknown>
  times: number[]
  values: number[]
  end: number | null
}

const ORACLE: Record<string, OracleCase> = JSON.parse(
  fs.readFileSync(
    path.resolve(path.dirname(fileURLToPath(import.meta.url)), "fixtures/motion-default-oracle.json"),
    "utf8"
  )
)

const BOX = { width: 100, height: 50 }
/** Where the box is at rest, which `x` and `y` are an offset from. */
const ORIGIN = 200

/** How a key's value shows in the box's bounds. */
const READ: Record<string, (box: { x: number; y: number; width: number; height: number }) => number> = {
  x: (box) => box.x - ORIGIN,
  y: (box) => box.y - ORIGIN,
  translateX: (box) => box.x - ORIGIN,
  width: (box) => box.width,
  height: (box) => box.height,
  scale: (box) => box.width / BOX.width,
  scaleX: (box) => box.width / BOX.width,
  scaleY: (box) => box.height / BOX.height,
}

/** A spring is Motion's numeric generator against a closed form here, and the clocks start a frame apart. */
const TOLERANCE = { pixels: 0.6, factor: 0.006 }

function frame(renderer: TestRenderer, ms: number): void {
  renderer.clockFastForward(ms)
  renderer.flush()
  renderer.dispatchNativeEvents()
}

function sample(case_: OracleCase): number[] {
  const app = createTestRoot({ width: 800, height: 600 })
  const renderer = app.renderer
  renderer.clockPause()
  const style = { ...BOX, backgroundColor: "#336699" }
  const written = (value: unknown) => ({ [case_.key]: value })
  const box =
    case_.target === undefined ? (
      <motion.div
        testId="box"
        style={style}
        initial={written(case_.from)}
        animate={written(case_.to)}
        transition={case_.transition}
      />
    ) : (
      <motion.div
        testId="box"
        style={style}
        initial="off"
        animate="on"
        variants={{ off: written(case_.from), on: { ...written(case_.to), transition: case_.target } }}
        transition={case_.transition}
      />
    )
  app.render(<div style={{ display: "flex", flexDirection: "column", alignItems: "flex-start", padding: ORIGIN }}>{box}</div>)
  const read = READ[case_.key]!
  let at = 0
  return case_.times.map((time) => {
    frame(renderer, Math.round((time - at) * 1000))
    at = time
    const bounds = renderer.getElementBounds(renderer.findByTestId("box").id)
    expect(bounds).not.toBeNull()
    return read(bounds!)
  })
}

describeNative("the default transition of a motion key", () => {
  const cases = Object.entries(ORACLE).filter(([, case_]) => case_.key in READ)

  it("covers every kind of key and transition", () => {
    expect(cases.length).toBeGreaterThan(70)
  })

  for (const [name, case_] of cases) {
    it(name, () => {
      const got = sample(case_)
      const unit = case_.key.startsWith("scale") ? TOLERANCE.factor : TOLERANCE.pixels
      case_.values.forEach((want, index) => {
        expect(Math.abs(got[index]! - want), `${name} at ${case_.times[index]} s: ${got[index]} is not ${want}`).toBeLessThanOrEqual(
          unit
        )
      })
    })
  }
})
